cat > notes/ent_summary.py <<'EOF'
import novamind_api as nm, json
def q(sql): return nm.query(sql)['rows']
day = nm.vars.current_day
print("DAY", day)
threads = q("""SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, MAX(t.turn_number) turns, MIN(t.day) first_day, MAX(t.day) last_day, MAX(t.seat_count) seats, MAX(t.closed) closed, MAX(t.close_reason) reason
FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id GROUP BY t.thread_id ORDER BY t.thread_id""")
last = {r['thread_id']: r for r in q("""SELECT thread_id, turn_number, sender, day, message_text, offer_json FROM enterprise_turns WHERE message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)""")}
open_new, awaiting, closed = [], [], []
for th in threads:
    l = last[th['thread_id']]
    row = dict(th=th['thread_id'], cid=th['customer_id'], grp=th['group_id'], type=th['thread_type'], seats=th['seats'], turns=th['turns'], first=th['first_day'], last_day=l['day'], sender=l['sender'], msg=(l['message_text'] or '')[:90], offer=l['offer_json'])
    if th['closed']:
        row['reason'] = th['reason']; closed.append(row)
    elif l['sender'] in ('system', 'customer'):
        awaiting.append(row)
    else:
        open_new.append(row)
print(f"\n### CLOSED ({len(closed)})")
for r in closed: print("  ", r)
print(f"\n### AWAITING MY RESPONSE ({len(awaiting)})")
for r in awaiting: print("  ", r)
print(f"\n### WAITING ON CUSTOMER ({len(open_new)})")
for r in open_new: print("  ", {k: r[k] for k in ('th','cid','grp','seats','turns','last_day')})
print("\n### enterprise subscriptions (subscribed)")
for r in q("SELECT c.group_id, s.customer_id, s.plan, s.listed_price, s.seat_count, s.start_day, s.status FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' AND s.status='subscribed' ORDER BY s.start_day"): print("  ", r)
print("\n### enterprise seat usage (last day) per group/plan")
for r in q(f"SELECT c.group_id, s.plan, COUNT(*) n_cust, SUM(s.seat_count) seats, SUM(u.usage_units) units, ROUND(1.0*SUM(u.usage_units)/SUM(s.seat_count),1) units_per_seat FROM daily_usage u JOIN subscriptions s ON s.customer_id=u.customer_id AND s.status='subscribed' JOIN customers c ON c.customer_id=u.customer_id WHERE c.customer_type='large' AND u.day={day-1} GROUP BY c.group_id, s.plan"): print("  ", r)
print("\n### enterprise payments this week")
for r in q(f"SELECT l.day, l.amount, l.note FROM ledger l WHERE l.category='subscription_payment' AND l.day>{day-7} AND l.amount>=500 ORDER BY l.amount DESC LIMIT 15"): print("  ", r)
EOF
