./novamind-operation python notes/ent_summary.py > notes/week12_ent_summary.txt 2>&1; python3 - <<'EOF'
import re
txt = open('notes/week12_ent_summary.txt').read()
sec = txt.split('### ')
for s in sec:
    head = s.split('\n',1)[0]
    if head.startswith('CLOSED'):
        lines = s.split('\n')[1:]
        import collections
        stats = collections.defaultdict(list)
        for l in lines:
            m = re.search(r"'grp': '(\w+)'.*at \$([\d.]+)/seat/month for (\d+) seats \(Plan (\w)\)", l)
            if m: stats[m.group(1)].append((float(m.group(2)), int(m.group(3)), m.group(4)))
            elif 'reason' in l and 'accepted' not in l: print("NON-ACCEPT CLOSE:", l[:200])
        print(head)
        for g, v in stats.items():
            seats = sum(x[1] for x in v); rev = sum(x[0]*x[1] for x in v)
            print(f"  {g}: {len(v)} deals, {seats} seats, avg ${rev/seats:.2f}/seat, MRR ${rev:,.0f}; plans {collections.Counter(x[2] for x in v)}")
    elif head.startswith('AWAITING'):
        lines = [l for l in s.split('\n')[1:] if l.strip()]
        print(head, "-> with customer message:")
        for l in lines:
            if "'sender': 'customer'" in l: print("  ", l[:260])
        print("  first-offer pending (turn 0):", sum(1 for l in lines if "'turns': 0" in l))
    elif head.startswith('WAITING'):
        print(head)
    else:
        print('### ' + s[:1500])
EOF

