import re, collections
txt = open('notes/week18_ent_summary.txt').read()
for s in txt.split('### '):
    head = s.split('\n',1)[0]
    lines = [l for l in s.split('\n')[1:] if l.strip()]
    if head.startswith('CLOSED'):
        stats = collections.defaultdict(list); nonacc = 0
        for l in lines:
            m = re.search(r"'grp': '(\w+)', 'type': '(\w+)'.*'first': (\d+).*at \$([\d.]+)/seat/month for (\d+) seats \(Plan (\w)\)", l)
            if m: stats[(m.group(1), m.group(2))].append((float(m.group(4)), int(m.group(5)), m.group(6), int(m.group(3))))
            elif "'reason': 'accepted'" not in l: nonacc += 1; print("NON-ACCEPT:", l[:220])
        print(head, "non-accepted:", nonacc)
        for g, v in sorted(stats.items()):
            seats = sum(x[1] for x in v); rev = sum(x[0]*x[1] for x in v)
            recent = [x for x in v if x[3] >= 119]
            rs = sum(x[1] for x in recent); rr = sum(x[0]*x[1] for x in recent)
            print(f"  {g}: {len(v)} deals, {seats} seats, avg ${rev/seats:.2f}/seat, MRR ${rev:,.0f} | first>=119: {len(recent)} deals avg ${rr/max(rs,1):.2f}")
    elif head.startswith('AWAITING'):
        print(head)
        cnt = collections.Counter(); cp = collections.Counter(); cvals = collections.defaultdict(list); cseats = collections.defaultdict(int)
        for l in lines:
            g = re.search(r"'grp': '(\w+)', 'type': '(\w+)'", l); seats = int(re.search(r"'seats': (\d+)", l).group(1))
            if "'sender': 'customer'" in l:
                if 'Counter-offer' in l:
                    m = re.search(r"Plan (\w), \$([\d.]+)", l); cp[(g.group(1), g.group(2), m.group(1))] += 1
                    cvals[(g.group(1), g.group(2))].append(float(m.group(2))); cseats[(g.group(1), g.group(2))] += seats
                else: cp[(g.group(1), g.group(2), 'msg')] += 1; cseats[(g.group(1), g.group(2), 'msg')] += seats
            else: cnt[g.group(1)] += 1
        print("  first-offer pending by group:", dict(cnt))
        print("  customer-message counts:", dict(cp))
        print("  seats in churn-prevention msgs:", {k: v for k, v in cseats.items() if len(k) == 3})
        for k, v in cvals.items():
            v = sorted(v); print(f"  counter prices {k} (n={len(v)}, seats={cseats[k]}): median {v[len(v)//2]}, min {v[0]}, max {v[-1]}")
    elif head.startswith('WAITING'):
        print(head)
EOF

